<?php declare(strict_types=1); namespace Annam; $title='Orders & billing'; ?>
<div class="o-actions"><a class="o-btn o-btn-primary" href="/manage/orders/new/">+ Create booking</a></div><form class="o-filters"><input name="q" placeholder="Search order, customer or phone" value="<?= e($_GET['q']??'') ?>"><select name="channel"><option value="">All channels</option><?php foreach(['web','manual','whatsapp'] as $channel): ?><option <?= ($_GET['channel']??'')===$channel?'selected':'' ?>><?= e($channel) ?></option><?php endforeach; ?></select><button class="o-btn">Search</button></form>
<div class="o-table-wrap"><table class="o-table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Payment</th></tr></thead><tbody><?php foreach($records as $record): ?><tr><td><a href="/manage/orders/<?= e($record['id']) ?>/"><strong><?= e($record['order_no']) ?></strong></a><small><?= e($record['channel'].' · '.$record['placed_at']) ?></small></td><td><?= e($record['customer_name']) ?><small><?= e($record['customer_phone']) ?></small></td><td><?= money($record['total']) ?></td><td><?= e(str_replace('_',' ',$record['status'])) ?></td><td><?= e($record['payment_status']) ?></td></tr><?php endforeach; ?><?php if(!$records): ?><tr><td colspan="5">No orders yet.</td></tr><?php endif; ?></tbody></table></div>
